use anyhow::Result;
use std::{fmt::Write as _, fs, path::Path};

use crate::{
    course::{Course, Kind, package_name},
    fsutil::{write_file, write_if_changed, write_if_missing},
    i18n::{Locale, tr},
    originals::{Originals, hash},
};

pub const GENERATED_HEADER: &str =
    "# Generated by rustlings. It is rewritten when the course changes.";
const VSCODE_HEADER: &str =
    "// Generated by rustlings. Remove this line to keep your own settings.";

pub const RUST_ANALYZER_TOML: &[u8] = br#"check.command = "clippy"
check.extraArgs = ["--profile", "test"]
cargo.targetDir = true
"#;

pub const GITIGNORE: &[u8] = b"Cargo.lock
target/
.vscode/
.rustlings-backup-*/
";

pub const VSCODE_EXTENSIONS_JSON: &[u8] = br#"{"recommendations":["rust-lang.rust-analyzer"]}"#;

pub const BASICS_LINTS: &str = "[lints.rust]
unsafe_code = \"forbid\"
unstable_features = \"forbid\"
dead_code = \"allow\"

[lints.clippy]
todo = \"forbid\"
empty_loop = \"forbid\"
infinite_loop = \"deny\"
mem_forget = \"deny\"
";

pub fn render_key(key: &str) -> String {
    if !key.is_empty()
        && key
            .bytes()
            .all(|c| c.is_ascii_alphanumeric() || c == b'_' || c == b'-')
    {
        key.to_owned()
    } else {
        render_string(key)
    }
}

pub fn render_string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            '\r' => out.push_str("\\r"),
            c if c.is_control() => {
                let _ = write!(out, "\\u{:04X}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

pub fn render_value(value: &toml::Value, support_path: &str) -> String {
    match value {
        toml::Value::String(s) => render_string(s),
        toml::Value::Integer(i) => i.to_string(),
        toml::Value::Float(f) => f.to_string(),
        toml::Value::Boolean(b) => b.to_string(),
        toml::Value::Datetime(d) => d.to_string(),
        toml::Value::Array(items) => {
            let items = items
                .iter()
                .map(|v| render_value(v, support_path))
                .collect::<Vec<_>>();
            format!("[{}]", items.join(", "))
        }
        toml::Value::Table(table) => {
            let items = table
                .iter()
                .map(|(k, v)| {
                    let rendered = match (k.as_str(), v) {
                        ("path", toml::Value::String(p)) if p.starts_with("@support") => {
                            render_string(&p.replacen("@support", support_path, 1))
                        }
                        _ => render_value(v, support_path),
                    };
                    format!("{} = {rendered}", render_key(k))
                })
                .collect::<Vec<_>>();
            format!("{{ {} }}", items.join(", "))
        }
    }
}

pub fn root_manifest(course: &Course) -> String {
    let mut exclude = vec!["exercises", "solutions", "support"];
    for journey in &course.journeys {
        if !exclude.contains(&journey.dir.as_str()) {
            exclude.push(&journey.dir);
        }
    }
    let exclude = exclude
        .iter()
        .map(|s| render_string(s))
        .collect::<Vec<_>>()
        .join(", ");
    format!(
        "{GENERATED_HEADER}
[workspace]
resolver = \"3\"
members = [\"tracks/*\"]
exclude = [{exclude}]
"
    )
}

pub fn track_manifest(course: &Course, track_ind: usize) -> Option<String> {
    if !course.track_has_file_exercises(track_ind) {
        return None;
    }
    let track = &course.tracks[track_ind];
    let mut out = format!(
        "{GENERATED_HEADER}
[package]
name = \"{}\"
version = \"0.0.0\"
edition = \"2024\"
publish = false
autobins = false
autoexamples = false
autotests = false
autobenches = false
",
        package_name(&track.id),
    );
    for ex in &course.exercises[course.track_exercises(track_ind)] {
        if ex.kind != Kind::File {
            continue;
        }
        let _ = write!(
            out,
            "\n[[bin]]\nname = {}\npath = {}\n",
            render_string(&ex.name),
            render_string(&format!("../../{}", ex.src)),
        );
    }
    out.push_str("\n[dependencies]\n");
    for (name, spec) in &track.dependencies {
        let _ = writeln!(
            out,
            "{} = {}",
            render_key(name),
            render_value(spec, "../../support")
        );
    }
    if track.id == "rust-basics" {
        out.push('\n');
        out.push_str(BASICS_LINTS);
    }
    Some(out)
}

pub fn linked_projects(course: &Course, root: &Path) -> Vec<String> {
    let mut projects = vec!["Cargo.toml".to_owned()];
    for ex in &course.exercises {
        if ex.kind == Kind::Project {
            let manifest = format!("{}/Cargo.toml", ex.src);
            if root.join(&manifest).is_file() {
                projects.push(manifest);
            }
        }
    }
    for journey in &course.journeys {
        let manifest = format!("{}/Cargo.toml", journey.dir);
        if root.join(&manifest).is_file() {
            projects.push(manifest);
        }
    }
    projects
}

pub fn vscode_settings(course: &Course, root: &Path) -> String {
    let projects = linked_projects(course, root)
        .iter()
        .map(|p| format!("    {}", render_string(p)))
        .collect::<Vec<_>>()
        .join(",\n");
    format!("{VSCODE_HEADER}\n{{\n  \"rust-analyzer.linkedProjects\": [\n{projects}\n  ]\n}}\n")
}

pub fn write_vscode_settings(course: &Course, root: &Path) -> Result<()> {
    let path = root.join(".vscode/settings.json");
    if let Ok(old) = std::fs::read_to_string(&path)
        && !old.starts_with(VSCODE_HEADER)
    {
        return Ok(());
    }
    write_if_changed(&path, vscode_settings(course, root).as_bytes())?;
    Ok(())
}

pub fn write_workspace(course: &Course, root: &Path) -> Result<()> {
    write_if_changed(root.join("Cargo.toml"), root_manifest(course).as_bytes())?;
    for track_ind in 0..course.tracks.len() {
        if let Some(manifest) = track_manifest(course, track_ind) {
            let path = format!("tracks/{}/Cargo.toml", course.tracks[track_ind].id);
            write_if_changed(root.join(path), manifest.as_bytes())?;
        }
    }
    write_vscode_settings(course, root)
}

pub fn write_support(course: &Course, root: &Path) -> Result<()> {
    for (path, content) in course.fs.under("course/support") {
        let rel = &path["course/".len()..];
        write_if_changed(root.join(rel), content)?;
    }
    Ok(())
}

fn milestone_internal(rel_in_chapter: &str, milestones: &[&str]) -> bool {
    milestones.iter().any(|m| {
        rel_in_chapter
            .strip_prefix(m)
            .and_then(|rest| rest.strip_prefix('/'))
            .is_some_and(|inner| inner != "README.md" && inner != "arch.toml")
    })
}

pub fn chapter_files(
    course: &Course,
    chapter_ind: usize,
    locale: Locale,
) -> Vec<(String, &'static [u8])> {
    let chapter = &course.chapters[chapter_ind];
    let dir = chapter.exercises_dir();
    let milestones = course.exercises[chapter.exercises.clone()]
        .iter()
        .filter(|e| e.kind == Kind::Milestone)
        .map(|e| e.name.as_str())
        .collect::<Vec<_>>();
    course
        .fs
        .tree(&dir, locale.as_str())
        .into_iter()
        .filter(|(rel, _)| rel != "chapter.toml" && !milestone_internal(rel, &milestones))
        .map(|(rel, content)| (format!("{dir}/{rel}"), content))
        .collect()
}

pub fn project_files(
    course: &Course,
    src_dir: &str,
    locale: Locale,
) -> Vec<(String, &'static [u8])> {
    course
        .fs
        .tree(src_dir, locale.as_str())
        .into_iter()
        .map(|(rel, content)| (format!("{src_dir}/{rel}"), content))
        .collect()
}

fn always_fresh(chapter_dir: &str, path: &str) -> bool {
    path.ends_with(".md") || path.starts_with(&format!("{chapter_dir}/visuals/"))
}

pub fn materialize_chapter(
    course: &Course,
    root: &Path,
    chapter_ind: usize,
    locale: Locale,
    originals: &mut Originals,
) -> Result<()> {
    for (path, content) in chapter_files(course, chapter_ind, locale) {
        write_file(root.join(&path), content)?;
        originals.set(&path, content);
    }
    Ok(())
}

pub fn update_chapter(
    course: &Course,
    root: &Path,
    chapter_ind: usize,
    locale: Locale,
    originals: &mut Originals,
    outdated: &mut Vec<String>,
) -> Result<()> {
    let chapter = &course.chapters[chapter_ind];
    let chapter_dir = chapter.exercises_dir();
    let projects = course.exercises[chapter.exercises.clone()]
        .iter()
        .filter(|e| e.kind == Kind::Project && root.join(&e.src).is_dir())
        .map(|e| format!("{}/", e.src))
        .collect::<Vec<_>>();
    for (path, content) in chapter_files(course, chapter_ind, locale) {
        let target = root.join(&path);
        let recorded = originals.get(&path);
        let Ok(current) = fs::read(&target) else {
            let in_project = projects.iter().any(|p| path.starts_with(p.as_str()));
            if in_project && (recorded.is_some() || !originals.existed()) {
                continue;
            }
            write_file(&target, content)?;
            originals.set(&path, content);
            continue;
        };
        if current == content {
            if recorded != Some(hash(content)) {
                originals.set(&path, content);
            }
            continue;
        }
        if always_fresh(&chapter_dir, &path) || recorded == Some(hash(&current)) {
            write_file(&target, content)?;
            originals.set(&path, content);
        } else if recorded.is_some_and(|h| h != hash(content)) {
            outdated.push(path);
        }
    }
    Ok(())
}

pub fn write_static_files(course: &Course, root: &Path) -> Result<()> {
    let t = tr();
    write_if_missing(root.join("README.md"), t.learner_readme.as_bytes())?;
    write_if_missing(
        root.join("solutions/README.md"),
        t.solutions_readme.as_bytes(),
    )?;
    write_if_missing(root.join(".gitignore"), GITIGNORE)?;
    write_if_changed(root.join("rust-analyzer.toml"), RUST_ANALYZER_TOML)?;
    write_if_missing(root.join(".vscode/extensions.json"), VSCODE_EXTENSIONS_JSON)?;
    if let Some(compose) = course.fs.get("course/docker-compose.yml") {
        write_if_missing(root.join("docker-compose.yml"), compose)?;
    }
    Ok(())
}

pub fn init_layout(course: &Course, root: &Path, locale: Locale) -> Result<()> {
    let mut originals = Originals::load(root);
    for chapter_ind in 0..course.chapters.len() {
        materialize_chapter(course, root, chapter_ind, locale, &mut originals)?;
    }
    originals.save(root)?;
    write_support(course, root)?;
    write_static_files(course, root)?;
    write_workspace(course, root)
}

pub fn sync(course: &Course, root: &Path, locale: Locale) -> Result<Vec<String>> {
    let mut originals = Originals::load(root);
    let mut outdated = Vec::new();
    for chapter_ind in 0..course.chapters.len() {
        update_chapter(
            course,
            root,
            chapter_ind,
            locale,
            &mut originals,
            &mut outdated,
        )?;
    }
    originals.save(root)?;
    write_support(course, root)?;
    write_static_files(course, root)?;
    write_workspace(course, root)?;
    Ok(outdated)
}

pub fn outdated_exercises(course: &Course, paths: &[String]) -> Vec<usize> {
    course
        .exercises
        .iter()
        .enumerate()
        .filter(|(_, ex)| {
            paths.iter().any(|p| match ex.kind {
                Kind::File => *p == ex.src,
                Kind::Project | Kind::Milestone => p.starts_with(&format!("{}/", ex.src)),
                Kind::Question => false,
            })
        })
        .map(|(ind, _)| ind)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::course::tests::fixture_fs;

    #[test]
    fn manifests() {
        let course = Course::load(fixture_fs()).unwrap();
        let root = root_manifest(&course);
        assert!(root.contains("members = [\"tracks/*\"]"));
        assert!(
            root.contains("exclude = [\"exercises\", \"solutions\", \"support\", \"backend\"]")
        );

        let basics = track_manifest(&course, 0).unwrap();
        assert!(basics.contains("name = \"basics-exercises\""));
        assert!(basics.contains(
            "[[bin]]\nname = \"intro1\"\npath = \"../../exercises/basics/00_intro/intro1.rs\"\n"
        ));
        assert!(!basics.contains("proj"));
        assert!(!basics.contains("ms_one"));

        let svc = track_manifest(&course, 1).unwrap();
        assert!(svc.contains("course-support = { features = [\"pg\"], path = \"../../support\" }"));
        assert!(svc.contains("tokio = { features = [\"full\"], version = \"1\" }"));
        toml::de::from_str::<toml::Table>(&svc).unwrap();
        toml::de::from_str::<toml::Table>(&basics).unwrap();
        toml::de::from_str::<toml::Table>(&root).unwrap();
    }

    fn versioned(v: &str) -> &'static Course {
        let leak = |s: String| -> &'static [u8] { s.into_bytes().leak() };
        let files: Vec<(&'static str, &'static [u8])> = vec![
            (
                "course/course.toml",
                b"format_version = 2\n[[tracks]]\nid = \"t\"\nchapters = [\"c\"]\n",
            ),
            (
                "exercises/t/c/chapter.toml",
                b"[chapter]\ntitle = \"c\"\n[[exercises]]\nname = \"a\"\n[[exercises]]\nname = \"b\"\n[[exercises]]\nname = \"p\"\nkind = \"project\"\n",
            ),
            ("exercises/t/c/README.md", leak(format!("readme {v}\n"))),
            ("exercises/t/c/visuals/x.html", leak(format!("<p>{v}</p>\n"))),
            ("exercises/t/c/a.rs", leak(format!("// a {v}\nfn main() {{}}\n"))),
            ("exercises/t/c/b.rs", leak(format!("// b {v}\nfn main() {{}}\n"))),
            ("exercises/t/c/p/Cargo.toml", b"[workspace]\n"),
            ("exercises/t/c/p/src/lib.rs", leak(format!("// lib {v}\n"))),
            ("exercises/t/c/p/src/gone.rs", b"// gone\n"),
        ];
        let mut files = files;
        if v == "v2" {
            files.push(("exercises/t/c/p/tests/new.rs", b"// new test\n"));
        }
        let fs = Box::leak(Box::new(crate::embedded::ContentFs::from_entries(&files)));
        Box::leak(Box::new(Course::load(fs).unwrap()))
    }

    #[test]
    fn updates_untouched_files_and_flags_edited_ones() {
        let root = std::env::temp_dir().join(format!("rustlings-update-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();
        let read = |p: &str| fs::read_to_string(root.join(p)).unwrap();
        let v1 = versioned("v1");
        init_layout(v1, &root, Locale::En).unwrap();
        assert!(root.join(crate::originals::FILE).is_file());

        fs::write(root.join("exercises/t/c/b.rs"), "// mine\nfn main() {}\n").unwrap();
        fs::write(root.join("exercises/t/c/README.md"), "my notes\n").unwrap();
        fs::remove_file(root.join("exercises/t/c/p/src/gone.rs")).unwrap();
        assert!(sync(v1, &root, Locale::En).unwrap().is_empty());
        assert!(!root.join("exercises/t/c/p/src/gone.rs").exists());
        assert_eq!(read("exercises/t/c/README.md"), "readme v1\n");

        let v2 = versioned("v2");
        let outdated = sync(v2, &root, Locale::En).unwrap();
        assert_eq!(read("exercises/t/c/a.rs"), "// a v2\nfn main() {}\n");
        assert_eq!(read("exercises/t/c/b.rs"), "// mine\nfn main() {}\n");
        assert_eq!(read("exercises/t/c/p/src/lib.rs"), "// lib v2\n");
        assert_eq!(read("exercises/t/c/README.md"), "readme v2\n");
        assert_eq!(read("exercises/t/c/visuals/x.html"), "<p>v2</p>\n");
        assert_eq!(read("exercises/t/c/p/tests/new.rs"), "// new test\n");
        assert!(!root.join("exercises/t/c/p/src/gone.rs").exists());
        assert_eq!(outdated, ["exercises/t/c/b.rs"]);
        assert_eq!(outdated_exercises(v2, &outdated), [1]);

        assert_eq!(sync(v2, &root, Locale::En).unwrap(), ["exercises/t/c/b.rs"]);
        fs::write(root.join("exercises/t/c/b.rs"), "// b v2\nfn main() {}\n").unwrap();
        assert!(sync(v2, &root, Locale::En).unwrap().is_empty());
        fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn render_strings() {
        assert_eq!(render_string("a\"b\\c\n"), "\"a\\\"b\\\\c\\n\"");
        assert_eq!(render_key("serde_json"), "serde_json");
        assert_eq!(render_key("a.b"), "\"a.b\"");
    }
}
